using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings",
    Description = "Returns application configuration data")]
public class ConfigResource
{
    public static McpServerResourceResponse Get()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Production",
            Features = new { EnableCaching = true, MaxConnections = 100 }
        };

        var json = JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });

        return new McpServerResourceResponse(new ModelContextProtocol.Protocol.Types.ResourceContents
        {
            Uri = "config://app/settings",
            MimeType = "application/json",
            Text = json
        });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server time in UTC")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("o");
    }

    [McpServerTool, Description("Echoes a message back with server metadata")]
    public static object Echo([Description("The message to echo")] string message)
    {
        return new { Echo = message, Timestamp = DateTime.UtcNow, Server = "McpHttpServer" };
    }
}

